package com.agacostays.billing.client;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;import org.springframework.core.ParameterizedTypeReference;import java.math.BigDecimal;import java.util.*;
@Component public class RestaurantServiceClient{private final RestClient c;public RestaurantServiceClient(@Value("${service.restaurant.url}")String u,RestClient.Builder b){c=b.baseUrl(u).build();}public List<RestaurantCharge> getOrdersForBooking(Long bookingId){try{List<Dto> x=c.get().uri("/api/restaurant/orders/by-booking/{id}",bookingId).retrieve().body(new ParameterizedTypeReference<List<Dto>>(){});return x==null?List.of():x.stream().map(d->new RestaurantCharge(d.orderId(),d.bookingId(),d.orderAmount(),d.orderStatus())).toList();}catch(Exception e){return List.of();}}public record Dto(Long orderId,Long bookingId,BigDecimal orderAmount,String orderStatus){}public record RestaurantCharge(Long orderId,Long bookingId,BigDecimal amount,String orderStatus){}}
